INSERT INTO player_test_cases (suite, module, tc_code, title, tc_type, priority, preconditions, steps, test_data, expected, admin_check, images, order_index, created_by) VALUES ('bonuses', 'Bonus - Tiketi', 'BTK-001', 'Aktivni bonusi se nude u bet slipu', 'Pozitivni', 'High', 'Igrač je prijavljen na staging-2 i ima ACTIVE bonuse (npr. "Marketing 3 Simple bonus" € 20,00: min. kvota 1.20; "Marketing simple on registration josip" € 15,00: min. kvota 1.60, min. kvota događaja 1.50).
Otvorena početna stranica (Sports).', '["Klikni na bilo koju kvotu da dodaš selekciju u bet slip.", "Pogledaj dio bet slipa ispod Amount."]', '', 'Bet slip prikazuje sve ACTIVE bonus walletove kao checkboxove sa nazivom i iznosom (npr. "Marketing 3 Simple bonus - € 20,00").
Bonusi u statusu PENDING i NOT ACCEPTED se NE nude (provjereno na stagingu – free betovi koji čekaju depozit nisu u listi).
Nijedan bonus nije unaprijed označen – zadano se igra novcem sa Main Walleta.', '', '[{"src": "/player-guide/btk-01-bonus-1-2.jpg", "caption": "Bonus odabran, kvota 1.03 → poruka o min. kvoti 1.2"}]', 0, 'Claude');
INSERT INTO player_test_cases (suite, module, tc_code, title, tc_type, priority, preconditions, steps, test_data, expected, admin_check, images, order_index, created_by) VALUES ('bonuses', 'Bonus - Tiketi', 'BTK-002', 'Samo jedan bonus po tiketu', 'Pozitivni', 'Medium', 'Igrač je prijavljen na staging-2 i ima ACTIVE bonuse (npr. "Marketing 3 Simple bonus" € 20,00: min. kvota 1.20; "Marketing simple on registration josip" € 15,00: min. kvota 1.60, min. kvota događaja 1.50).
Otvorena početna stranica (Sports).', '["Dodaj selekciju.", "Označi prvi bonus.", "Označi drugi bonus."]', '', 'Može biti označen samo jedan bonus: odabir drugog isključuje prvi (provjereno na stagingu).', '', '[{"src": "/player-guide/btk-02-bonus-1-5.jpg", "caption": "Drugi bonus odabran (prvi se isključio) → poruka 1.5, Book/Proceed neaktivni"}]', 1, 'Claude');
INSERT INTO player_test_cases (suite, module, tc_code, title, tc_type, priority, preconditions, steps, test_data, expected, admin_check, images, order_index, created_by) VALUES ('bonuses', 'Bonus - Tiketi', 'BTK-003', 'Minimalna kvota događaja uz bonus', 'Negativni', 'High', 'Igrač je prijavljen na staging-2 i ima ACTIVE bonuse (npr. "Marketing 3 Simple bonus" € 20,00: min. kvota 1.20; "Marketing simple on registration josip" € 15,00: min. kvota 1.60, min. kvota događaja 1.50).
Otvorena početna stranica (Sports).', '["Dodaj selekciju sa kvotom 1.03.", "Označi \"Marketing 3 Simple bonus\" (min. 1.20).", "Označi \"Marketing simple on registration josip\" (min. kvota događaja 1.50).", "Zamijeni selekciju selekcijom sa kvotom ≥ 1.60."]', '', 'Uz kvotu ispod minimuma prikazuje se poruka "Selections must have odds not lower than 1.2 when bonus wallet is selected" (odnosno 1.5 za drugi bonus), a Book i Proceed su neaktivni (provjereno na stagingu).
Sa kvotom koja ispunjava uslov poruka nestaje i tiket se može uplatiti.', '', '[{"src": "/player-guide/btk-01-bonus-1-2.jpg", "caption": "Bonus odabran, kvota 1.03 → poruka o min. kvoti 1.2"}, {"src": "/player-guide/btk-02-bonus-1-5.jpg", "caption": "Drugi bonus odabran (prvi se isključio) → poruka 1.5, Book/Proceed neaktivni"}]', 2, 'Claude');
INSERT INTO player_test_cases (suite, module, tc_code, title, tc_type, priority, preconditions, steps, test_data, expected, admin_check, images, order_index, created_by) VALUES ('bonuses', 'Bonus - Tiketi', 'BTK-004', 'Minimalna UKUPNA kvota uz bonus', 'Granične vrijednosti', 'High', 'Igrač je prijavljen na staging-2 i ima ACTIVE bonuse (npr. "Marketing 3 Simple bonus" € 20,00: min. kvota 1.20; "Marketing simple on registration josip" € 15,00: min. kvota 1.60, min. kvota događaja 1.50).
Otvorena početna stranica (Sports).', '["Označi bonus \"josip\" (min. ukupna kvota 1.60, min. kvota događaja 1.50).", "Dodaj jednu selekciju sa kvotom između 1.50 i 1.59 (npr. 1.55).", "Dodaj kombinaciju dvije selekcije 1.30 × 1.30 (ukupno 1.69, ali događaji ispod 1.50).", "Dodaj selekciju tačno 1.60, pa tačno 1.50 + 1.10…"]', '', '1 selekcija 1.55: blokirano – ukupna kvota je ispod 1.60.
1.30 × 1.30: blokirano – događaji su ispod 1.50.
Tačno 1.60 (i događaji ≥ 1.50): dozvoljeno.
Poruka jasno kaže koji uslov nije ispunjen.
Napomena: na stagingu poruka za ovaj bonus spominje samo 1.5 (kvota događaja), ne i ukupnu kvotu 1.60 – provjeriti da se provjerava i ukupna kvota.', '', '[]', 3, 'Claude');
INSERT INTO player_test_cases (suite, module, tc_code, title, tc_type, priority, preconditions, steps, test_data, expected, admin_check, images, order_index, created_by) VALUES ('bonuses', 'Bonus - Tiketi', 'BTK-005', 'Minimalan broj selekcija uz bonus', 'Negativni', 'Medium', 'Igrač je prijavljen na staging-2 i ima ACTIVE bonuse (npr. "Marketing 3 Simple bonus" € 20,00: min. kvota 1.20; "Marketing simple on registration josip" € 15,00: min. kvota 1.60, min. kvota događaja 1.50).
Otvorena početna stranica (Sports).
U adminu postoji bonus sa Minimum selection = 2.', '["Označi bonus sa min. 2 selekcije.", "Uplati sa 1 selekcijom.", "Dodaj drugu selekciju."]', '', 'Sa 1 selekcijom tiket je blokiran porukom o minimalnom broju selekcija; sa 2 je dozvoljen.', '', '[]', 4, 'Claude');
INSERT INTO player_test_cases (suite, module, tc_code, title, tc_type, priority, preconditions, steps, test_data, expected, admin_check, images, order_index, created_by) VALUES ('bonuses', 'Bonus - Tiketi', 'BTK-006', 'Uspješna uplata tiketa bonusom', 'Pozitivni', 'High', 'Igrač je prijavljen na staging-2 i ima ACTIVE bonuse (npr. "Marketing 3 Simple bonus" € 20,00: min. kvota 1.20; "Marketing simple on registration josip" € 15,00: min. kvota 1.60, min. kvota događaja 1.50).
Otvorena početna stranica (Sports).
Zabilježeni Main Wallet i bonus walleti (Overview).', '["Dodaj selekcije koje ispunjavaju sve uslove bonusa.", "Označi bonus, unesi ulog (npr. 5 €).", "Klikni Proceed i potvrdi.", "Provjeri balans u zaglavlju, Overview, My Account → Bonuses, Transaction list i Sport Tickets."]', 'Ulog: 5 €', 'Tiket je uplaćen.
Ulog je skinut SA BONUS WALLETA (Available Amount bonusa manji za 5 €), a Main Wallet je nepromijenjen.
Transaction list: Bet iz bonus walleta.
Sport Tickets: tiket je vidljiv i označen kao bonus tiket (ako je predviđeno).
Nakon obračuna promet bonusa (% already wagered) raste.', 'U adminu tiket je vezan za bonus wallet igrača, a promet bonusa je ažuriran.', '[]', 5, 'Claude');
INSERT INTO player_test_cases (suite, module, tc_code, title, tc_type, priority, preconditions, steps, test_data, expected, admin_check, images, order_index, created_by) VALUES ('bonuses', 'Bonus - Tiketi', 'BTK-007', 'Ulog veći od iznosa bonusa', 'Negativni', 'High', 'Igrač je prijavljen na staging-2 i ima ACTIVE bonuse (npr. "Marketing 3 Simple bonus" € 20,00: min. kvota 1.20; "Marketing simple on registration josip" € 15,00: min. kvota 1.60, min. kvota događaja 1.50).
Otvorena početna stranica (Sports).', '["Označi bonus od € 20,00.", "Unesi ulog 25 €.", "Pokušaj Proceed."]', '', 'Tiket se blokira porukom o nedovoljnom bonus balansu – ili se razlika uzima sa Main Walleta, ako je tako definisano (provjeriti sa PO).
Nikad nema negativnog bonus balansa.', '', '[]', 6, 'Claude');
INSERT INTO player_test_cases (suite, module, tc_code, title, tc_type, priority, preconditions, steps, test_data, expected, admin_check, images, order_index, created_by) VALUES ('bonuses', 'Bonus - Tiketi', 'BTK-008', 'Dobitni i gubitni tiket uplaćen bonusom', 'Pozitivni', 'High', 'Igrač je prijavljen na staging-2 i ima ACTIVE bonuse (npr. "Marketing 3 Simple bonus" € 20,00: min. kvota 1.20; "Marketing simple on registration josip" € 15,00: min. kvota 1.60, min. kvota događaja 1.50).
Otvorena početna stranica (Sports).
Uplaćena dva bonus tiketa (BTK-006): jedan će dobiti, jedan izgubiti.', '["Sačekaj obračun oba tiketa.", "Provjeri bonus wallet, Main Wallet, Withdrawable i stranicu Bonuses."]', '', 'Dobitak ide na bonus wallet (ne na Main/Withdrawable) dok promet nije završen.
Gubitni tiket smanjuje bonus wallet i ulazi u promet.
Red "Bonus (0%)" u Possible Winnings jasno objašnjava šta znači.', 'U adminu dobitak je knjižen na bonus wallet, a promet tačno izračunat.', '[]', 7, 'Claude');
INSERT INTO player_test_cases (suite, module, tc_code, title, tc_type, priority, preconditions, steps, test_data, expected, admin_check, images, order_index, created_by) VALUES ('bonuses', 'Bonus - Tiketi', 'BTK-009', 'Free bet u bet slipu', 'Pozitivni', 'High', 'Igrač ima ACTIVE free bet (npr. prihvaćen preko BFE-003).', '["Dodaj selekcije koje ispunjavaju uslove free beta.", "Označi free bet.", "Uplati i sačekaj obračun."]', '', 'Free bet se nudi u bet slipu, a ulog je jednak iznosu free beta (ne može se mijenjati, ili prema pravilima).
Kod dobitka isplaćuje se samo dobitak bez uloga (provjeriti sa PO).
Free bet prelazi u Used.', '', '[]', 8, 'Claude');
INSERT INTO player_test_cases (suite, module, tc_code, title, tc_type, priority, preconditions, steps, test_data, expected, admin_check, images, order_index, created_by) VALUES ('bonuses', 'Bonus - Tiketi', 'BTK-010', 'Igranje bez bonusa uz aktivne bonuse', 'Pozitivni', 'Medium', 'Igrač je prijavljen na staging-2 i ima ACTIVE bonuse (npr. "Marketing 3 Simple bonus" € 20,00: min. kvota 1.20; "Marketing simple on registration josip" € 15,00: min. kvota 1.60, min. kvota događaja 1.50).
Otvorena početna stranica (Sports).', '["Dodaj selekciju sa kvotom 1.03.", "Ne označavaj nijedan bonus i uplati mali ulog."]', '', 'Bez označenog bonusa nema provjere minimalne kvote bonusa; ulog ide sa Main Walleta, a bonusi ostaju netaknuti.', '', '[]', 9, 'Claude');
INSERT INTO player_test_cases (suite, module, tc_code, title, tc_type, priority, preconditions, steps, test_data, expected, admin_check, images, order_index, created_by) VALUES ('bonuses', 'Bonus - Tiketi', 'BTK-011', 'Promjena kvote i live selekcije uz bonus', 'Negativni', 'Medium', 'Igrač je prijavljen na staging-2 i ima ACTIVE bonuse (npr. "Marketing 3 Simple bonus" € 20,00: min. kvota 1.20; "Marketing simple on registration josip" € 15,00: min. kvota 1.60, min. kvota događaja 1.50).
Otvorena početna stranica (Sports).', '["Dodaj live selekciju čija kvota je blizu minimuma bonusa (npr. 1.22 uz min. 1.20).", "Označi bonus i sačekaj da kvota padne ispod minimuma (uz \"Allow Odd Changes\" uključeno i isključeno)."]', '', 'Kad kvota padne ispod minimuma, bet slip odmah prikazuje poruku i blokira Proceed – tiket se ne smije prihvatiti ispod minimalne kvote bonusa, ni uz Allow Odd Changes.', '', '[]', 10, 'Claude');
INSERT INTO player_test_cases (suite, module, tc_code, title, tc_type, priority, preconditions, steps, test_data, expected, admin_check, images, order_index, created_by) VALUES ('bonuses', 'Bonus - Tiketi', 'BTK-012', 'Izgled neaktivnih dugmadi u bet slipu', 'UI/UX', 'Medium', 'Igrač je prijavljen na staging-2 i ima ACTIVE bonuse (npr. "Marketing 3 Simple bonus" € 20,00: min. kvota 1.20; "Marketing simple on registration josip" € 15,00: min. kvota 1.60, min. kvota događaja 1.50).
