INSERT INTO player_test_cases (suite, module, tc_code, title, tc_type, priority, preconditions, steps, test_data, expected, admin_check, images, order_index, created_by) VALUES ('bonuses', 'Bonus - Tiketi', 'BTK-014', 'Bonus u kombinaciji sa One Cut insure i Book', 'Negativni', 'Medium', 'Igrač je prijavljen na staging-2 i ima ACTIVE bonuse (npr. "Marketing 3 Simple bonus" € 20,00: min. kvota 1.20; "Marketing simple on registration josip" € 15,00: min. kvota 1.60, min. kvota događaja 1.50).
